#!/usr/bin/env python3"""Diagnose the job API 500 error - capture full response."""import requestsimport jsonBASE_URL = "http://127.0.0.1:8000/api/v1"def get_token():    """Get auth token."""    resp = requests.post(f"{BASE_URL}/auth/login", data={"username": "test@example.com", "password": "password123"})    if resp.status_code == 200:        return resp.json()["access_token"]    return Nonetoken = get_token()if not token:    print("FAIL: Could not authenticate")    exit(1)headers = {"Authorization": f"Bearer {token}"}print("[1] Testing GET /jobs/")print("-" * 80)resp = requests.get(f"{BASE_URL}/jobs/", headers=headers)print(f"Status: {resp.status_code}")print(f"Response: {resp.text[:1000]}")print()print("[2] Testing POST /jobs/ (create)")print("-" * 80)job_data = {    "title": "Test",    "description": "Test",    "location": "Remote",    "company_name": "Test",    "employment_type": "Full-time",    "experience_level": "Mid",    "work_mode": "Remote",    "industry": "Tech",}resp = requests.post(f"{BASE_URL}/jobs/", json=job_data, headers=headers)print(f"Status: {resp.status_code}")if resp.status_code in [200, 201]:    job_id = resp.json().get("_id") or resp.json().get("id")    print(f"Created job: {job_id}")    print()        print("[3] Testing PATCH /jobs/{job_id}")    print("-" * 80)    resp = requests.patch(f"{BASE_URL}/jobs/{job_id}", json={"title": "Updated"}, headers=headers)    print(f"Status: {resp.status_code}")    print(f"Response: {resp.text[:1000]}")    print()        print("[4] Testing DELETE /jobs/{job_id}")    print("-" * 80)    resp = requests.delete(f"{BASE_URL}/jobs/{job_id}", headers=headers)    print(f"Status: {resp.status_code}")    print(f"Response: {resp.text[:1000]}")else:    print(f"Response: {resp.text[:1000]}")